"""Render expanded procurement content using captured specifications and focused profiles."""
import importlib.util
editorial_spec=importlib.util.spec_from_file_location('packhub_expanded',ROOT/'content/expanded.py')
expanded_content=importlib.util.module_from_spec(editorial_spec);editorial_spec.loader.exec_module(expanded_content)

def prose_section(id,title,text):
 return '<section id="'+id+'"><h2>'+esc(title)+'</h2><p>'+esc(text)+'</p></section>'

def question_list(items):
 return '<div class="faq">'+''.join('<details><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>' for q,a in items)+'</div>'

def product_profile(record):
 if record.get('profile'):return record['profile']
 groups=set(record['groups'])
 if '953304411' in groups:return 'display'
 if '803759676' in groups:return 'label'
 if groups&{'807897313','952983140'}:return 'print'
 name=record['name'].lower()
 if 'display' in name:return 'display'
 if any(s in name for s in ['sticker','label']):return 'label'
 if any(s in name for s in ['card','tag','booklet']) and 'box' not in name:return 'print'
 if 'pouch' in record['detail']['title'].lower() and '919632767' in record['groups']:return 'pouch'
 if 'bag' in name:
  return 'bag' if 'paper' in name or 'kraft' in name else 'poly'
 if any(s in name for s in ['magnetic','drawer','lid & base','gift box','tube']):return 'rigid'
 if any(s in name for s in ['mailer','shipping','corrugated']):return 'mailer'
 return 'carton'

def product_editorial(record,rows):
 profile=product_profile(record);name=record['name'];reference=record['reference']
 material=next((v for k,v in rows if k in ['Material reference','Film reference','Other film reference']),'Complete material construction to confirm')
 size=next((v for k,v in rows if k=='Dimensions reference'),'Finished dimensions and measurement convention to confirm')
 printing=next((v for k,v in rows if k in ['Printing options','Print / finish options']),'Print route and finishing to confirm with the artwork')
 application=next((v for k,v in rows if k=='Application'),'the intended product and use conditions')
 opening=next((v for k,v in rows if k=='Opening'),'the opening shown on the approved construction drawing')
 component=record['format'] in ['container-reference','pulp-insert']
 flexible=record['family']=='bags'
 print_piece=profile in ['print','label','sleeve','dust-cover']
 features=('component, dimensions, material, print surface and items included in the quotation' if component else 'finished size, paper, cut or fold layout, printed panels and any attachment or adhesive requirements' if print_piece else 'complete material, finished dimensions, seams, opening and requested features' if flexible else 'board, finished dimensions, opening, any insert and printed finish')
 if profile=='insert':features='cavity dimensions, support points, paper furnish, wall geometry, nesting and outer-pack fit'
 elif profile=='dust-cover':features='cover outline, paper, wick clearance, removal feature and approved print'
 elif profile=='sleeve':features='underlying pack dimensions, wrap length, paper, fold layout, closing method and print'
 elif profile=='print':features='finished size, paper, printed panels, fold or cut layout and attachment where needed'
 elif profile=='label':features='finished shape, label material, adhesive, backing supply and print'
 quantity_note=('For roll supply, list the unit count and roll configuration separately.' if profile in ['roll-bag','label'] else 'For a set, list the quantity and specification of each included component.' if component or profile=='bag-in-box' else 'Confirm the quantity for each size and printed design in the written quotation.')
 sample_focus=('scope, fit and printed appearance of the component being supplied' if component else 'application, fit, readable print and the handling of the finished piece' if print_piece else 'filled fit, opening, seams and the planned packing method' if flexible else 'product fit, assembly, opening and the complete packing arrangement')
 if profile=='insert':sample_focus='cavity fit, support, removal access, nesting and interaction with the actual outer pack'
 body='<section class="section softbg"><div class="wrap tank-layout"><nav class="tank-nav" aria-label="On this product page"><h2>Plan your packaging</h2>'+''.join('<a href="#'+id+'">'+title+'</a>' for id,title in [('reference-specification','This reference'),('product-design','Structure & use'),('customization','Customization'),('sample-review','Samples & quality'),('order-planning','Order planning'),('product-questions','Product FAQ')])+'</nav><article class="tank-content">'
 body+=prose_section('reference-specification','Review '+name.lower(),f'Use {reference} to identify this image and its reference details when contacting PackHubGlobe. Material reference: {material}. Size reference: {size}. Printing or finishing reference: {printing}. These entries describe starting points for a custom specification, not an approved bill of materials or a fixed stock item. Review the {features} together and identify any requested changes. Confirm one final construction and artwork revision in the written quotation and sample approval. Catalog orders start at 500 pieces.')
 if record['format'] in POUCH_FORMATS:
  body+=prose_section('reference-use','Contents and opening to confirm',f'The application direction recorded for this reference is {application}. Describe the actual contents, target fill mass or volume, storage conditions and packing method before selecting the final construction. The opening reference is {opening}. Confirm which features will be included on your drawing and inspect them on a matching sample. Printed product names and claims in the image are presentation examples. They do not qualify the material for your intended contact conditions or filling process; agree the relevant evidence for the selected construction.')
 for i,(title,text) in enumerate(expanded_content.PROFILES[profile]):
  body+=prose_section('product-design' if i==0 else 'design-'+str(i),title,text)
 body+=prose_section('customization','Define the changes for your order',f'Use the image to explain which details you want to retain and which should change. For this reference, review the {features}. Provide the actual product or companion package, measurements, quantity per design and artwork status. Confirm structural or application decisions before placing important text on the final drawing. If the order includes several components, list their individual quantities and explain how they fit together in packing, display or delivery. Keep the approved version of each component identifiable throughout the quotation and sample review.')
 body+='<h3>Your specification checklist</h3><ul><li>Reference '+reference+' and the exact component or complete pack to be supplied.</li><li>Finished dimensions with units, and fill quantity only where relevant to the format.</li><li>Quantity per size and artwork version, starting from 500 pieces.</li><li>'+esc(features.capitalize())+'.</li><li>Artwork files, sample priorities, destination and target arrival window.</li></ul>'
 body+=prose_section('sample-review','Review a sample for the actual task',f'Select the sample according to the decision still open. For this format, the review should cover {sample_focus}. A blank sample can resolve construction and fit, while an appropriate printed reference helps review artwork and surface appearance. Confirm how closely the sample material and production route represent the proposed order. Agree the checks and conditions before approval, record the findings and identify the sample revision. If the material, size, opening or application changes, review the affected decision again rather than carrying it over from an unrelated example.')
 body+=prose_section('order-planning','MOQ, quotation and delivery planning',f'Catalog orders start at 500 pieces. State the quantity for each size and printed design so the quotation can identify the production split and the component being counted. {quantity_note} Ask for setup or tooling, samples, product supply, export packing and freight to be explained where applicable. Production scheduling follows the agreed specification and approvals, while delivery also depends on the destination and shipping arrangement. Include the required arrival window and confirm revised terms when artwork, quantities or packing change.')
 faq_items=[('What is the MOQ for '+reference+'?',f'Catalog orders start at 500 pieces. Confirm the unit being quoted and how the quantity is divided across sizes, artwork versions or included components. {quantity_note}'),('Can I request my own logo and dimensions?','Share the reference, product or companion-pack measurements and artwork status. We will review the component, printable area, dimensions and requested finish together before confirming the specification and sample.'),('Which material and print details should I review?',f'The material starting point is {material}. The print or finish reference is {printing}. Confirm the complete construction and one final print specification rather than treating a list of reference options as features automatically included in the order.'),('What should I send for an accurate quote?',f'Include {reference}, the actual component or pack required, dimensions with units, quantity per design, the {features}, sample priorities and delivery country. For filled packs, also describe the contents and filling conditions.'),('Can the image be used as production approval?','Use the image to communicate the design direction. Approve physical fit, printed color and the relevant functional checks using the final specification and an appropriate sample for the actual component and application.'),('How do I place a repeat order?','Share the previous reference and approved artwork revision. Confirm whether the product, companion package, material, size, printed information or delivery arrangement has changed, then review affected sample checks before repeating production.')]
 body+='<section id="product-questions"><h2>'+esc(name)+' questions</h2>'+question_list(faq_items)+'</section><section><h2>Useful buying guides</h2><p>Prepare a <a href="/guides/packaging-quote-checklist/">complete packaging quote brief</a>, choose the right <a href="/guides/packaging-sample-types/">sample type</a>, and review what a <a href="/guides/packaging-print-proof/">print proof should confirm</a>. Compare relevant <a href="/materials/">materials and finishes</a> using the actual construction for your order.</p></section></article></div></section>'
 return body

def guide_extra(slug):
 data=expanded_content.GUIDE_EXPANSIONS[slug]
 body='<div class="guide-answer"><strong>Quick answer</strong><p>'+esc(data['answer'])+'</p></div>'
 body+=prose_section('worked-example','A worked procurement example',data['example'])
 body+='<h2 id="comparison">Compare the decisions that matter</h2>'+table(data['rows'])
 body+='<section id="common-mistakes"><h2>Common mistakes to avoid</h2><ul>'+''.join('<li>'+esc(s)+'</li>' for s in data['mistakes'])+'</ul><p>Use the comparison above to identify what is still unknown. Ask for a written answer or a suitable sample where a purchasing decision depends on that point. An unanswered requirement is easier to resolve before artwork, tooling or a production quantity is approved than after the order has been scheduled.</p></section>'
 body+='<section id="approval-checklist"><h2>Your approval checklist</h2><ul>'+''.join('<li>'+esc(s)+'</li>' for s in data['checks'])+'</ul><p>Keep this checklist with the specification and the people responsible for product, artwork and purchasing approval. Give each file and sample a clear revision. If an item remains open, identify who will answer it and which part of the order depends on the answer. This makes the approval useful to the next person reviewing the package, rather than leaving important decisions in an email thread or a photograph without context.</p></section>'
 body+=prose_section('approval-record','Turn the findings into a clear approval record','Record the reference reviewed, the conditions or contents used, the findings and the changes requested. Distinguish a design direction from an approved production specification. When several people are involved, identify who approves wording, structure, printed appearance and the commercial terms. Keep the final artwork and the relevant physical reference together. If a later revision changes one decision, review the affected parts explicitly rather than silently treating every earlier approval as valid for the new version.')
 body+='<section id="guide-faq"><h2>Frequently asked questions</h2>'+question_list(data['faq'])+'</section><h2>Apply this to your packaging project</h2><p>Use <a href="/guides/packaging-quote-checklist/">the quote checklist</a> to assemble your brief, then explore <a href="'+data['links'][0]+'">relevant packaging options</a> or discuss <a href="'+data['links'][1]+'">the related specification decision</a>. Start with what you know and label the points you want us to help resolve.</p>'
 sources=[('Adobe: print color management','https://helpx.adobe.com/illustrator/using/printing-color-management.html'),('ISTA: selecting package test procedures','https://www.ista.org/test_procedures.php')]
 if slug in ['internal-vs-external-box-dimensions','paper-bag-load-testing','label-roll-direction']:sources=[('GS1: package measurement standard','https://www.gs1.org/standards/gs1-package-and-product-measurement-standard/current-standard'),('ISTA: reviewing changed packaged products','https://support.ista.org/portal/en/kb/articles/when-should-a-packaged-product-be-retested')]
 if slug=='label-roll-direction':sources[1]=('GS1: code placement on retail packaging','https://ref.gs1.org/guidelines/2d-in-retail/')
 if slug in ['mailer-boxes-vs-shipping-boxes','folding-cartons-vs-rigid-boxes']:sources[0]=('FEFCO: corrugated design style references','https://www.fefco.org/technical-information/fefco-code')
 body+='<section class="article-note"><h2>Technical references and further reading</h2><p>These references explain relevant measurement, print or test-planning concepts. They do not certify the products shown on this website.</p><ul>'+''.join('<li><a href="'+url+'" target="_blank" rel="noopener noreferrer">'+esc(title)+'</a></li>' for title,url in sources)+'</ul></section>'
 return body

def home_family_cards():
 body='<section class="section softbg" id="packaging"><div class="wrap"><div class="sectionhead centered"><h2>Choose your packaging family.</h2><p>Start with the structure, then compare a reference and make the details your own.</p></div><div class="home-family-grid">'
 for title,path,text in [('Paper boxes','paper-boxes','Explore folding cartons, corrugated mailers, rigid gift boxes, magnetic boxes and drawer structures. Compare the opening experience, usable space and product protection around the way you sell and ship.'),('Bags & pouches','bags','Find paper shopping bags, paper mailing bags, garment bags, poly mailers and printed pouches. Begin with the contents, carrying or filling workflow, closure and the surface your customer will handle.'),('Packaging accessories','packaging-accessories','Complete the pack with cards, hang tags, labels, stickers and display accessories. Coordinate the graphic identity while choosing the paper, attachment or adhesive for the actual application.')]:
  image_index={'paper-boxes':0,'bags':1,'packaging-accessories':4}[path]
  body+='<article class="home-family-card"><a href="/catalog/'+path+'/" aria-label="Explore '+title.lower()+'">'+art(image_index)+'</a><div class="home-family-copy"><h3><a href="/catalog/'+path+'/">'+title+'</a></h3><p>'+text+'</p><a class="textlink" href="/catalog/'+path+'/">Explore '+title.lower()+' ↗</a></div></article>'
 return body+'</div></div></section>'

def expanded_home():
 body='<section class="section wrap"><div class="sectionhead"><div><h2>Custom printed packaging, specified for your product.</h2><p>A good packaging project connects product fit, printed branding and the way the finished order is handled.</p></div></div><div class="two"><section><h3>Start with the complete contents</h3><p>Share the product, dimensions or fill quantity, accessories and any existing retail pack. A carton around a bottle, a presentation box around a set and a mailer around the whole order create different requirements. Tell us how the package will be displayed, filled, carried or shipped so the structure can be reviewed around its real job.</p><p>Our catalog brings together packaging images and reference specifications across boxes, bags, pouches and printed accessories. Use a PHG reference to identify a direction, then explain the changes you need. This keeps the conversation tied to a specific example while leaving room to resolve dimensions, materials, closure and artwork for your brand.</p></section><section><h3>Plan print and material together</h3><p>Paperboard, kraft paper, rigid wraps, films and label materials interact differently with print and finishing. Identify your important logo colors and the surfaces customers will see. Discuss foil, embossing, coating or clear-film white ink where relevant to the selected reference rather than assuming the same instructions suit every material.</p><p>Review the right sample for each decision. A structural sample can answer fit and assembly questions, while a suitable printed reference helps with artwork and appearance. Keep approvals attached to the material, dieline and artwork revision that will actually be used.</p></section></div></section><section class="section softbg"><div class="wrap split"><div><span class="eyebrow">Orders from 500 pieces</span><h2>A clearer brief. A more useful quotation.</h2><p>Custom catalog products start at 500 pieces. List quantities by product, size and printed design, especially when your project includes several components. Identify the delivery country, sample priorities and target arrival window so your request can be reviewed as a complete order.</p><p>Compare quotations using the same specification. Ask which costs relate to setup, samples, production, export packing and freight where applicable. Price and timing are confirmed for the agreed order; a catalog photograph is the starting point for the conversation.</p><a class="textlink" href="/guides/packaging-quote-checklist/">Build a better packaging brief ↗</a></div><div><h3>Information to send with your enquiry</h3><ul class="home-checklist"><li>Product reference or the packaging format you need.</li><li>Product measurements, fill quantity or a sample to review.</li><li>Quantity per size and artwork version, from 500 pieces.</li><li>Material, closure, insert and finishing priorities.</li><li>Artwork status, sample needs and delivery destination.</li></ul><a class="button" href="/request-quote/">Discuss your packaging project</a></div></div></section>'
 return body


def home_selling_points():
 points=[('Factory-direct supply','Work with a packaging manufacturing team in China, from structure to finished print.','/factory/'),('One-stop packaging','Coordinate custom boxes, bags, pouches, cards and labels through one supplier.','/catalog/'),('Across your industry','Packaging for e-commerce, food, beauty, apparel and retail brands.','/industries/'),('Free samples','Start the conversation with a sample request and the formats you want to compare.','/request-quote/?product=Free%20sample%20request')]
 return '<section class="home-selling" aria-label="Why source with PackHubGlobe"><div class="wrap home-selling-grid">'+''.join('<a href="'+url+'"><span class="selling-mark" aria-hidden="true">'+str(i+1).zfill(2)+'</span><h2>'+title+'</h2><p>'+text+'</p><span class="selling-arrow" aria-hidden="true">↗</span></a>' for i,(title,text,url) in enumerate(points))+'</div></section>'

def home_production():
 stages=[('plate-making','Plate making','Prepare the plates and cutting tools around the approved artwork and dieline.'),('paper-cutting','Paper cutting','Cut paper and board to the sheet sizes planned for the job.'),('printing','Offset printing','Print the artwork with the agreed CMYK or spot-color specification.'),('coating','Coating','Apply the selected varnish or coating to the printed surface.'),('lamination','Lamination','Apply matte or gloss film when the chosen specification calls for it.'),('corrugating','Corrugated mounting','Mount the printed sheet to corrugated board for the selected box structure.'),('die-cutting','Die cutting','Cut and crease the printed sheets into the approved packaging shape.'),('gluing','Folding & gluing','Fold, glue and assemble the structure for its final packing checks.')]
 body='<section class="section home-production" id="production"><div class="wrap"><div class="sectionhead process-heading"><div><span class="eyebrow">Inside paper packaging production</span><h2>Follow the making of your packaging.</h2><p>Eight stages from preparation to assembly. The production route depends on your structure, material and finish.</p></div><div class="process-controls" aria-label="Production gallery controls"><button type="button" data-process-prev aria-label="Previous production step" aria-controls="production-rail">←</button><button type="button" data-process-toggle aria-pressed="false" aria-controls="production-rail">Pause motion</button><button type="button" data-process-next aria-label="Next production step" aria-controls="production-rail">→</button></div></div></div><div class="process-rail" id="production-rail" tabindex="0" aria-label="Eight production stages; swipe or use the arrow controls"><ol class="process-track">'
 for i,(slug,title,text) in enumerate(stages):
  body+='<li class="process-stage"><img src="/assets/process/'+slug+'.webp" alt="'+title+' on the paper packaging production floor" width="1000" height="750" loading="lazy"><div class="process-stage-copy"><span class="process-number">'+str(i+1).zfill(2)+'</span><h3>'+title+'</h3><p>'+text+'</p></div></li>'
 return body+'</ol></div><div class="wrap process-caption"><p>Swipe to explore · Hover or focus to pause · Steps vary by order</p><a class="textlink" href="/factory/">View factory &amp; capabilities ↗</a></div><div class="wrap"><div class="home-quality"><div><span class="eyebrow">Before production approval</span><h3>Agree the details. Then make the pack.</h3><p>Confirm the material, artwork, sample and inspection requirements together. Foil stamping and other finishing steps are added when specified for your order.</p></div><ul><li>Structural design &amp; dieline support</li><li>Free sample options</li><li>Production &amp; pre-shipment checks</li><li>Order-specific material documentation</li></ul><a class="textlink" href="/guides/packaging-sample-types/">Plan your samples ↗</a></div></div></section>'

def home_inside():
 stories=[('sample-room','Compare the details in hand.','Explore packaging structures, printed finishes and inserts in the sample room. Use a reference to start your own specification.','Explore sample options','/services/sampling/','Packaging samples displayed on the shelves in the sample room'),('material-warehouse','Begin with the right material.','Paper, board and finishing choices are reviewed around your product, presentation and shipping requirements.','Explore materials & finishes','/materials/','Paper and board stock in the raw material warehouse'),('project-office','Bring the brief into focus.','Discuss dimensions, artwork, samples and delivery requirements with the project team before the production specification is confirmed.','Discuss your project','/request-quote/','Project coordination workspace at the packaging facility')]
 body='<section class="section wrap home-stories"><div class="sectionhead"><div><span class="eyebrow">Beyond the production line</span><h2>Real spaces. Practical conversations.</h2><p>Get a closer look at the samples, materials and people behind your packaging project.</p></div></div><div class="home-story-grid">'
 for image,title,text,label,url,alt in stories:
  body+='<article><a href="'+url+'"><img src="/assets/company/'+image+'.webp" alt="'+alt+'" width="1100" height="825" loading="lazy"></a><h3>'+title+'</h3><p>'+text+'</p><a class="textlink" href="'+url+'">'+label+' ↗</a></article>'
